return ['domain'=>'woocommerce-multilingual','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'WPML Multilingual & Multicurrency for WooCommerce 5.6.0','pot-creation-date'=>'2026-09-12T13:36:01+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Multilingual & Multicurrency for WooCommerce'=>'WPML Multilingual & Multicurrency for WooCommerce','https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml','Make your store multilingual and enable multiple currencies | <a href="https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml">Documentation</a>'=>'Uczyń swój sklep wielojęzycznym i włącz obsługę wielu walut | <a href="https://wpml.org/documentation/wpml-core-and-add-on-plugins/woocommerce-multilingual/?utm_source=plugin&utm_medium=gui&utm_campaign=wcml">Dokumentacja</a>','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Language of the content to read.'=>'Język treści do odczytu.','Currency for the returned prices.'=>'Waluta dla zwracanych cen.','WPML Multilingual & Multicurrency for WooCommerce detected an active cache plugin on your site.'=>'WPML Multilingual & Multicurrency for WooCommerce wykrył aktywną wtyczkę buforującą w Twojej witrynie.','Caching may cause currency display issues for your customers if you are using the multicurrency feature.'=>'Buforowanie może powodować problemy z wyświetlaniem walut u klientów, jeśli korzystasz z funkcji wielowalutowości.','To avoid this, set your cache plugin to not cache pages for visitors that have a cookie set in their browser.'=>'Aby tego uniknąć, ustaw wtyczkę buforującą tak, aby nie buforowała stron dla odwiedzających, którzy mają ustawione ciasteczko w przeglądarce.','Important: Action Needed for Your <b>Currency Switcher</b>'=>'Ważne: wymagane działanie dla Twojego <b>przełącznika walut</b>','We detected that your site is using a <b>Currency Switcher</b> built with Twig templates. For security reasons, support for Twig-based templates will be discontinued in the upcoming version of WPML Multilingual & Multicurrency for WooCommerce 5.6.'=>'Wykryliśmy, że Twoja witryna używa <b>przełącznika walut</b> zbudowanego przy użyciu szablonów Twig. Ze względów bezpieczeństwa wsparcie dla szablonów opartych na Twig zostanie wycofane w nadchodzącej wersji WPML Multilingual & Multicurrency for WooCommerce 5.6.','To ensure your <b>Currency Switcher</b> continues working smoothly:'=>'Aby zapewnić płynne działanie <b>przełącznika walut</b>:','- Switch to a PHP-based template - you can select one from the %1$sconfiguration page%2$s.'=>'- Przełącz się na szablon oparty na PHP – możesz go wybrać na %1$sstronie konfiguracji%2$s.','- Need a custom solution? %1$sContact our support%2$s - we’re here to help you migrate safely.'=>'- Potrzebujesz niestandardowego rozwiązania? %1$sSkontaktuj się z naszym wsparciem%2$s – jesteśmy tutaj, aby pomóc Ci w bezpiecznej migracji.','We recommend updating your <b>Currency Switcher</b> as soon as possible to avoid disruptions when the new version of WPML Multilingual & Multicurrency for WooCommerce is released.'=>'Zalecamy aktualizację <b>przełącznika walut</b> tak szybko, jak to możliwe, aby uniknąć zakłóceń po wydaniu nowej wersji WPML Multilingual & Multicurrency for WooCommerce.','Migrating your multilingual shop? With %s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'Migrujesz swój sklep wielojęzyczny? Dzięki %s możesz przenieść przetłumaczoną treść do nowej witryny, w tym sprzedaż krzyżową, sprzedaż up-sell i atrybuty produktów.','Looking to import your multilingual shop? With %1$s and %2$s in both your original and new site, you can export and import your translations automatically.'=>'Chcesz zaimportować swój sklep wielojęzyczny? Mając %1$s i %2$s zarówno w oryginalnej, jak i nowej witrynie, możesz automatycznie eksportować i importować swoje tłumaczenia.','WPML Export and Import'=>'WPML Export and Import','You haven\'t added any secondary currencies'=>'Nie dodano żadnych walut pomocniczych','Please add another currency to fully utilize multicurrency mode. If you do not need multiple currencies, you can disable this setting to improve your site\'s performance.'=>'Dodaj kolejną walutę, aby w pełni wykorzystać tryb wielowalutowy. Jeśli nie potrzebujesz wielu walut, możesz wyłączyć to ustawienie, aby poprawić wydajność witryny.','Configure multicurrency mode'=>'Skonfiguruj tryb wielowalutowy','Review WPML Multilingual & Multicurrency for WooCommerce'=>'Oceń WPML Multilingual & Multicurrency for WooCommerce','Congrats on making your first multicurrency sale!'=>'Gratulacje z okazji pierwszej sprzedaży wielowalutowej!','Want to help <strong>WPML Multilingual & Multicurrency for WooCommerce</strong> plugin? %1$sGive us a review%2$s!'=>'Chcesz pomóc wtyczce <strong>WPML Multilingual & Multicurrency for WooCommerce</strong>? %1$sWystaw nam opinię%2$s!','Currency - no orders found'=>'Waluta – nie znaleziono zamówień','Invalid nonce'=>'Nieprawidłowy klucz bezpieczeństwa (nonce)','WPML synced translations for product-level changes only.'=>'WPML zsynchronizował tłumaczenia tylko dla zmian na poziomie produktu.','WPML synced translations for %1$d of %2$d variations.'=>'WPML zsynchronizował tłumaczenia dla %1$d z %2$d wariantów.','%d other variation was not checked because its data didn\'t change here.'=>'%d inny wariant nie został sprawdzony, ponieważ jego dane nie uległy tutaj zmianie.' . "\0" . '%d inne warianty nie zostały sprawdzone, ponieważ ich dane nie uległy tutaj zmianie.' . "\0" . '%d innych wariantów nie zostało sprawdzonych, ponieważ ich dane nie uległy tutaj zmianie.','If you\'ve made changes <strong>outside this editor</strong> (for example, retranslating an attribute term), use <em>%s</em> below to make sure every translation is current.'=>'Jeśli wprowadzono zmiany <strong>poza tym edytorem</strong> (na przykład ponownie przetłumaczono termin atrybutu), użyj przycisku <em>%s</em> poniżej, aby upewnić się, że każde tłumaczenie jest aktualne.','Force update all'=>'Wymuś aktualizację wszystkich','Force update all variation translations'=>'Wymuś aktualizację wszystkich tłumaczeń wariantów','You can switch to <em>"Always check all variations"</em> on the %s.'=>'Możesz przełączyć się na <em>„Zawsze sprawdzaj wszystkie warianty”</em> na %s.','WCML Settings page'=>'stronie ustawień WCML','(opens in a new tab)'=>'(otwiera się w nowej zakładce)','Syncing all variations…'=>'Synchronizowanie wszystkich wariantów…','Done — all variations synced'=>'Gotowe – wszystkie warianty zsynchronizowane','Sync completed for product #%d.'=>'Synchronizacja zakończona dla produktu #%d.','Failed — see console'=>'Niepowodzenie – sprawdź konsolę','Error — '=>'Błąd – ','Dismiss'=>'Odrzuć','WPML verified %1$d variation × %2$d language on this save. None of them had changes that needed syncing.'=>'WPML zweryfikował %1$d wariant × %2$d język przy tym zapisie. Żaden z nich nie zawierał zmian wymagających synchronizacji.' . "\0" . 'WPML zweryfikował %1$d warianty × %2$d języki przy tym zapisie. Żaden z nich nie zawierał zmian wymagających synchronizacji.' . "\0" . 'WPML zweryfikował %1$d wariantów × %2$d języków przy tym zapisie. Żaden z nich nie zawierał zmian wymagających synchronizacji.','That\'s wasted work. Switching to <em>"Only sync variations edited in the editor"</em> would make saves like this much faster — WPML will only sync the variations you actually changed and tell you what was skipped.'=>'To niepotrzebna praca. Przełączenie na <em>„Synchronizuj tylko warianty edytowane w edytorze”</em> znacznie przyspieszyłoby zapisywanie – WPML zsynchronizuje tylko te warianty, które faktycznie zostały zmienione, i poinformuje Cię, co zostało pominięte.','You can switch on the %s.'=>'Możesz to zmienić na %s.','Don\'t show this again on this site'=>'Nie pokazuj tego więcej w tej witrynie','Variation translation sync on product save'=>'Synchronizacja tłumaczeń wariantów przy zapisywaniu produktu','Choose how WPML updates variation translations when you save a variable product. Affects saves in the WooCommerce product editor only — Translation Dashboard and Translate Everything Automatically always run a complete sync.'=>'Wybierz, w jaki sposób WPML ma aktualizować tłumaczenia wariantów podczas zapisywania produktu z wariantami. Dotyczy to tylko zapisów w edytorze produktów WooCommerce – Pulpit tłumaczeń i Automatyczne tłumaczenie wszystkiego zawsze uruchamiają pełną synchronizację.','Choose how WPML updates variation translations when you save a variable product.'=>'Wybierz, w jaki sposób WPML ma aktualizować tłumaczenia wariantów podczas zapisywania produktu z wariantami.','Affects saves in the WooCommerce product editor only. <b>Translation Dashboard</b> and <b>Translate Everything</b> Automatically always run a complete sync.'=>'Dotyczy to tylko zapisów w edytorze produktów WooCommerce. <b>Pulpit tłumaczeń</b> i <b>Automatyczne tłumaczenie wszystkiego</b> zawsze uruchamiają pełną synchronizację.','Always check all variations'=>'Zawsze sprawdzaj wszystkie warianty','On every save, WPML checks every variation in every language and syncs anything that\'s out of date.'=>'Przy każdym zapisie WPML sprawdza każdy wariant w każdym języku i synchronizuje wszystko, co jest nieaktualne.','Only sync variations edited in the editor'=>'Synchronizuj tylko warianty edytowane w edytorze','WPML syncs only the variations changed in this save. After each save, WPML shows what was synced and offers a one-click full sync.'=>'WPML synchronizuje tylko warianty zmienione podczas tego zapisu. Po każdym zapisie WPML pokazuje, co zostało zsynchronizowane, i oferuje pełną synchronizację jednym kliknięciem.','To translate custom WooCommerce email notifications, go to the %1$sTranslation Dashboard%2$s.'=>'Aby przetłumaczyć niestandardowe powiadomienia e-mail WooCommerce, przejdź do %1$sPulpitu tłumaczeń%2$s.','Monthly on the %s'=>'Co miesiąc, dnia %s','Weekly on %s'=>'Co tydzień w %s','Cannot get exchange rates. Connection failed.'=>'Nie można pobrać kursów wymiany. Połączenie nie powiodło się.','Please note that the payment will be made in %1$s. Your total will be approximately %2$s, depending on the current exchange rate.'=>'Pamiętaj, że płatność zostanie dokonana w walucie %1$s. Łączna kwota wyniesie około %2$s, w zależności od aktualnego kursu wymiany.','Not yet supported'=>'Jeszcze nieobsługiwane','Set the currency in which your customer will see the final price when they checkout. Choose which accounts they will see in their payment message.'=>'Ustaw walutę, w której klient zobaczy ostateczną cenę podczas składania zamówienia. Wybierz konta, które zobaczy w wiadomości o płatności.','Currency'=>'Waluta','Bank Account'=>'Konto bankowe','All Accounts'=>'Wszystkie konta','All in selected currency'=>'Wszystkie w wybranej walucie','PayPal Email'=>'E-mail PayPal','Merchant ID'=>'Identyfikator sprzedawcy (Merchant ID)','Client ID'=>'Identyfikator klienta (Client ID)','Secret Key'=>'Klucz tajny (Secret key)','This gateway does not support %s. To show this gateway please select another currency.'=>'Ta bramka nie obsługuje waluty %s. Aby wyświetlić tę bramkę, wybierz inną walutę.','WPML could not read this payment from PayPal, so no refund was sent. Please try the refund again.'=>'WPML nie mógł odczytać tej płatności z PayPal, więc zwrot nie został wysłany. Spróbuj ponownie wykonać zwrot.','The refund amount is too small to send to PayPal in the currency of the payment, so no refund was sent. Refund a larger amount, or record the refund manually in WooCommerce.'=>'Kwota zwrotu jest zbyt niska, aby wysłać ją do PayPal w walucie płatności, więc zwrot nie został wysłany. Zwróć większą kwotę lub zarejestruj zwrot ręcznie w WooCommerce.','WPML could not work out how much to refund on this order, so no refund was sent. Check the exchange rate for the order\'s currency in WPML\'s multicurrency settings, then try the refund again.'=>'WPML nie mógł obliczyć kwoty zwrotu dla tego zamówienia, więc zwrot nie został wysłany. Sprawdź kurs wymiany dla waluty zamówienia w ustawieniach multicurrency WPML, a następnie spróbuj ponownie wykonać zwrot.','Live Publishable Key'=>'Klucz publiczny (Live)','Live Secret Key'=>'Klucz tajny (Live)','Test Publishable Key'=>'Klucz publiczny (Test)','Test Secret Key'=>'Klucz tajny (Test)','Connect with Stripe'=>'Połącz z Stripe','Connect a test account'=>'Połącz konto testowe','Reconnect with Stripe'=>'Połącz ponownie z Stripe','Reconnect the test account'=>'Połącz ponownie konto testowe','Connected with Stripe'=>'Połączono z Stripe','You will continue on Stripe. Save your changes first. Anything unsaved on this screen is lost.'=>'Nastąpi przekierowanie do Stripe. Najpierw zapisz zmiany. Niezapisane dane na tym ekranie zostaną utracone.','Stripe could not be connected. Please try again.'=>'Nie udało się połączyć ze Stripe. Spróbuj ponownie.','This payment is already refunded in full on Stripe, so no refund was sent. Record the refund manually in WooCommerce instead.'=>'Ta płatność została już w całości zwrócona w Stripe, więc zwrot nie został wysłany. Zamiast tego zarejestruj zwrot ręcznie w WooCommerce.','The refund amount is too small to send to Stripe in the currency of the payment, so no refund was sent. Refund a larger amount, or record the refund manually in WooCommerce.'=>'Kwota zwrotu jest zbyt niska, aby wysłać ją do Stripe w walucie płatności, więc zwrot nie został wysłany. Zwróć większą kwotę lub zarejestruj zwrot ręcznie w WooCommerce.','WPML could not read this payment from Stripe, so no refund was sent. Please try the refund again.'=>'WPML nie mógł odczytać tej płatności ze Stripe, więc zwrot nie został wysłany. Spróbuj ponownie wykonać zwrot.','PayPal took this payment in %1$s, and WooCommerce can only send a refund in %2$s. Refund this order in your PayPal account, then record it here with "Refund manually".'=>'PayPal przyjął tę płatność w %1$s, a WooCommerce może wysłać zwrot tylko w %2$s. Dokonaj zwrotu dla tego zamówienia na swoim koncie PayPal, a następnie zarejestruj go tutaj, wybierając „Zwróć ręcznie”.','Language'=>'Język','Costs and values in custom currencies'=>'Koszty i wartości w niestandardowych walutach','WPML Multilingual & Multicurrency for WooCommerce by default will multiply all your costs and values defined above by currency exchange rates. If you don\'t want this and you prefer static values instead, you can define them here.'=>'WPML Multilingual & Multicurrency for WooCommerce domyślnie pomnoży wszystkie koszty i wartości zdefiniowane powyżej przez kursy wymiany walut. Jeśli tego nie chcesz i wolisz zamiast tego wartości statyczne, możesz je zdefiniować tutaj.','Enable costs in custom currencies'=>'Włącz koszty w niestandardowych walutach','Calculate shipping costs in other currencies automatically'=>'Obliczaj koszty wysyłki w innych walutach automatycznie','Set shipping costs in other currencies manually'=>'Ustaw koszty wysyłki w innych walutach ręcznie','The label for the field with minimal order amount in additional currency. The currency symbol will be added in place of %s specifier.Minimal order amount in %s'=>'Minimalna kwota zamówienia w %s','The description for the field with minimal order amount in additional currency. The currency symbol will be added in place of %s specifier.The minimal order amount if customer choose %s as a purchase currency.'=>'Minimalna kwota zamówienia, jeśli klient wybierze %s jako walutę zakupu.','Your shipping class %1$s has been created in %2$s language. Please switch your language if you want to provide shipping costs in different currencies for this class.'=>'Twoja klasa wysyłkowa %1$s została utworzona w języku %2$s. Przełącz język, jeśli chcesz podać koszty wysyłki w innych walutach dla tej klasy.','"%1$s" shipping class cost in %2$s'=>'Koszt klasy wysyłkowej „%1$s” w %2$s','N/A'=>'N/D','No shipping class cost in %s'=>'Brak kosztu klasy wysyłkowej w %s','The label for the field with shipping cost in additional currency. The currency symbol will be added in place of %s specifier.Cost in %s'=>'Koszt w %s','The description for the field with shipping cost in additional currency. The currency symbol will be added in place of %s specifier.The shipping cost if customer choose %s as a purchase currency.'=>'Koszt wysyłki, jeśli klient wybierze %s jako walutę zakupu.','Your site needs HTTPS to connect a live Stripe account. You can still connect a test account.'=>'Twoja witryna wymaga protokołu HTTPS, aby połączyć aktywne konto Stripe. Nadal możesz połączyć konto testowe.','Stripe did not return a connection link. Please try again.'=>'Stripe nie zwrócił linku połączenia. Spróbuj ponownie.','Stripe is now connected for %s.'=>'Stripe jest teraz połączony dla %s.','Stripe could not be connected for %s. Please try again.'=>'Nie udało się połączyć Stripe dla %s. Spróbuj ponownie.','Currencies'=>'Waluty','Add currency'=>'Dodaj walutę','Rate'=>'Kurs','default'=>'domyślna','Edit'=>'Edytuj','Currency displayed first'=>'Waluta wyświetlana jako pierwsza','Choose which currency to display when a client switches languages'=>'Wybierz, która waluta ma być wyświetlana, gdy klient zmienia język','Keep'=>'Zachowaj','Delete'=>'Usuń','Currencies to display for each language'=>'Waluty do wyświetlenia dla każdego języka','Add a secondary currency to choose which currencies appear for each language.'=>'Dodaj walutę pomocniczą, aby wybrać, które waluty mają pojawiać się dla każdego języka.','Enable %1$s for %2$s'=>'Włącz %1$s dla %2$s','Disable %1$s for %2$s'=>'Wyłącz %1$s dla %2$s','Settings'=>'Ustawienia','Add new currency'=>'Dodaj nową walutę','Currency settings for %s'=>'Ustawienia waluty dla %s','Select currency'=>'Wybierz walutę','Exchange Rate'=>'Kurs wymiany','Only numeric'=>'Tylko cyfry','(previous value: %s)'=>'(poprzednia wartość: %s)','Currency Preview'=>'Podgląd waluty','Currency Position'=>'Pozycja symbolu waluty','Left'=>'Po lewej','Right'=>'Po prawej','Left with space'=>'Po lewej ze spacją','Right with space'=>'Po prawej ze spacją','Thousand Separator'=>'Separator tysięcy','(Space)'=>'(spacja)','Decimal Separator'=>'Separator dziesiętny','Number of Decimals'=>'Liczba miejsc po przecinku','Rounding to the nearest integer'=>'Zaokrąglanie do najbliższej liczby całkowitej','Disabled'=>'Wyłączone','Up'=>'W górę','Down'=>'W dół','Nearest'=>'Do najbliższej','Increment for nearest integer'=>'Skok dla najbliższej liczby całkowitej','The resulting price will be an increment of this value after initial rounding.%se.g.:'=>'Wynikowa cena będzie wielokrotnością tej wartości po początkowym zaokrągleniu.%snp.:','1454.07 &raquo; 1454 when set to 1'=>'1454.07 &raquo; 1454 przy ustawieniu 1','1454.07 &raquo; 1450 when set to 10'=>'1454.07 &raquo; 1450 przy ustawieniu 10','1454.07 &raquo; 1500 when set to 100'=>'1454.07 &raquo; 1500 przy ustawieniu 100','Round the converted price to the closest integer. %se.g. 15.78 becomes 16.00'=>'Zaokrąglij przeliczoną cenę do najbliższej liczby całkowitej. %snp. 15.78 staje się 16.00','The value to be subtracted from the amount obtained previously.'=>'Wartość, która zostanie odjęta od kwoty uzyskanej wcześniej.','For 1454.07, when the increment for the nearest integer is 100 and the auto-subtract amount is 1, the resulting amount is 1499.'=>'Dla 1454.07, gdy skok dla najbliższej liczby całkowitej wynosi 100, a kwota automatycznego odliczania wynosi 1, wynikowa kwota to 1499.','Autosubtract amount'=>'Kwota automatycznego odliczania','Payment Gateways'=>'Bramki płatnicze','Custom settings for %s'=>'Ustawienia niestandardowe dla %s','Learn more'=>'Dowiedz się więcej','Please enter a valid number'=>'Wprowadź poprawną liczbę','The currency was not saved. Try again.'=>'Waluta nie została zapisana. Spróbuj ponownie.','The setting was not saved. Try again.'=>'Ustawienie nie zostało zapisane. Spróbuj ponownie.','Cancel'=>'Anuluj','Save'=>'Zapisz','Currency available in'=>'Waluta dostępna w','All countries'=>'Wszystkie kraje','All countries except: '=>'Wszystkie kraje z wyjątkiem: ','All countries except...'=>'Wszystkie kraje z wyjątkiem...','Specific countries'=>'Konkretne kraje','Show currencies based on'=>'Pokaż waluty na podstawie','You need the WPML plugin to make your store multilingual and display currencies based on site language. Don\'t have it yet?'=>'Potrzebujesz wtyczki WPML, aby uczynić swój sklep wielojęzycznym i wyświetlać waluty na podstawie języka witryny. Jeszcze jej nie masz?','Purchase WPML now'=>'Kup WPML teraz','Site Language'=>'Język witryny','Client Location'=>'Lokalizacja klienta','Location based'=>'Na podstawie lokalizacji','WooCommerce integrates with MaxMind Geolocation to reliably determine the location of your customers.'=>'WooCommerce integruje się z MaxMind Geolocation, aby rzetelnie określić lokalizację Twoich klientów.','Great! Now you can use Geolocation to determine default currency for chosen languages. You can edit that key in '=>'Świetnie! Teraz możesz używać geolokalizacji do określania domyślnej waluty dla wybranych języków. Możesz edytować ten klucz na ','WooCommerce settings page.'=>'stronie ustawień WooCommerce.','MaxMind Licence Key'=>'Klucz licencyjny MaxMind','Apply'=>'Zastosuj','Please note: without a free MaxMind key, your geolocation calls will be limited and your site performance may be impacted.'=>'Uwaga: bez darmowego klucza MaxMind wywołania geolokalizacji będą ograniczone, co może wpłynąć na wydajność witryny.','Learn how to generate a free license key'=>'Dowiedz się, jak wygenerować darmowy klucz licencyjny','Set on %s'=>'Ustawiono %s','Country availability'=>'Dostępność w krajach','All countries except'=>'Wszystkie kraje z wyjątkiem','Configure per country availability for this payment gateway'=>'Skonfiguruj dostępność dla poszczególnych krajów dla tej bramki płatniczej','Save changes'=>'Zapisz zmiany','Settings saved.'=>'Ustawienia zapisane.','Error saving settings.'=>'Błąd podczas zapisywania ustawień.','We noticed that you\'re using WooCommerce Gateways Country Limiter plugin which is now integrated into WPML Multilingual & Multicurrency for WooCommerce. Please remove it!'=>'Zauważyliśmy, że używasz wtyczki WooCommerce Gateways Country Limiter, która jest teraz zintegrowana z WPML Multilingual & Multicurrency for WooCommerce. Usuń ją!','To translate custom text for payment methods, go to the %1$sTranslation Dashboard%2$s.'=>'Aby przetłumaczyć niestandardowy tekst dla metod płatności, przejdź do %1$sPulpitu tłumaczeń%2$s.','To translate permalinks for product taxonomies, go to %1$sWPML Multilingual & Multicurrency for WooCommerce → Store URLs%2$s.'=>'Aby przetłumaczyć bezpośrednie odnośniki dla taksonomii produktów, przejdź do %1$sWPML Multilingual & Multicurrency for WooCommerce → Store URLs%2$s.','To translate product permalinks, go to %1$sWPML Multilingual & Multicurrency for WooCommerce → Store URLs%2$s.'=>'Aby przetłumaczyć bezpośrednie odnośniki produktów, przejdź do %1$sWPML Multilingual & Multicurrency for WooCommerce → Store URLs%2$s.','How to translate permalinks for product taxonomies'=>'Jak tłumaczyć bezpośrednie odnośniki dla taksonomii produktów','How to translate product permalinks'=>'Jak tłumaczyć bezpośrednie odnośniki produktów','Translate WooCommerce products'=>'Przetłumacz produkty WooCommerce','Translate shipping classes'=>'Przetłumacz klasy wysyłkowe','Configure multicurrency for multilingual sites'=>'Skonfiguruj wielowalutowość dla witryn wielojęzycznych','Translate endpoints'=>'Przetłumacz punkty końcowe','How to translate this?'=>'Jak to przetłumaczyć?','WPML Multilingual & Multicurrency for WooCommerce will use cookies to understand the basket info when using languages in domains and to transfer data between the domains.'=>'WPML Multilingual & Multicurrency for WooCommerce będzie używać ciasteczek do zrozumienia informacji o koszyku podczas korzystania z języków w domenach oraz do przesyłania danych między domenami.','WPML Multilingual & Multicurrency for WooCommerce will also use cookies to identify the language and currency of each customer’s order as well as the currency of the reports created by WooCommerce. WPML Multilingual & Multicurrency for WooCommerce extends these reports by adding the currency’s information.'=>'WPML Multilingual & Multicurrency for WooCommerce będzie również używać ciasteczek do identyfikacji języka i waluty zamówienia każdego klienta, a także waluty raportów tworzonych przez WooCommerce. WPML Multilingual & Multicurrency for WooCommerce rozszerza te raporty, dodając informacje o walucie.','Invalid currency parameter: "%s"'=>'Nieprawidłowy parametr waluty: „%s”','Invalid language parameter: "%s"'=>'Nieprawidłowy parametr języka: „%s”','Product not found: %d'=>'Nie znaleziono produktu: %d','Term not found: %d'=>'Nie znaleziono terminu: %d','Using "translation_of" requires providing a "lang" parameter too'=>'Użycie „translation_of” wymaga również podania parametru „lang”','Multilingual'=>'Wielojęzyczność','Multicurrency'=>'Wielowalutowość','To run your store in multiple languages, you need to use the %1$sWPML plugin%2$s.'=>'Aby prowadzić sklep w wielu językach, musisz użyć %1$swtyczki WPML%2$s.','If you have it already, install and activate it. Otherwise, %1$sbuy WPML%2$s.'=>'Jeśli już ją masz, zainstaluj ją i aktywuj. W przeciwnym razie %1$skup WPML%2$s.','You will need either the Multilingual CMS or Multilingual Agency package to use WPML with WooCommerce.'=>'Do korzystania z WPML z WooCommerce potrzebujesz pakietu Multilingual CMS lub Multilingual Agency.','You can still use the %1$smulticurrency features%2$s without buying anything.'=>'Nadal możesz korzystać z %1$sfunkcji wielowalutowości%2$s bez kupowania czegokolwiek.','%s translation'=>'Tłumaczenie: %s','Translating %1$s? Use the %2$s table for easier translation.'=>'Tłumaczysz %1$s? Użyj tabeli %2$s, aby ułatwić sobie tłumaczenie.','To translate product details, including their taxonomy, use this dashboard. If you need to translate taxonomy independently or adjust store and currency settings, visit: %1$sWPML Multilingual & Multicurrency for WooCommerce documentation%2$s.'=>'Aby przetłumaczyć szczegóły produktu, w tym jego taksonomię, użyj tego pulpitu. Jeśli chcesz przetłumaczyć taksonomię niezależnie lub dostosować ustawienia sklepu i waluty, odwiedź: %1$sdokumentację WPML Multilingual & Multicurrency for WooCommerce%2$s.','To translate this content, go to the %1$sTranslation Dashboard%2$s.'=>'Aby przetłumaczyć tę treść, przejdź do %1$sPulpitu tłumaczeń%2$s.','To see how to translate this text, save your changes here first.'=>'Aby zobaczyć, jak przetłumaczyć ten tekst, najpierw zapisz tutaj swoje zmiany.','Header alignment for translations'=>'Wyrównanie nagłówka dla tłumaczeń','Automatically align email headers based on%slanguage direction (right-to-left or left-to-right).'=>'Automatycznie wyrównuj nagłówki wiadomości e-mail na podstawie%skierunku języka (od prawej do lewej lub od lewej do prawej).','Off – use the "Header alignment" setting above'=>'Wyłączone – użyj ustawienia „Wyrównanie nagłówka” powyżej','On – align automatically'=>'Włączone – wyrównuj automatycznie','Introduction'=>'Wprowadzenie','Store Pages'=>'Strony sklepu','Global Attributes'=>'Atrybuty globalne','Multiple Currencies'=>'Wiele walut','Tour Data'=>'Dane wycieczki','Title'=>'Tytuł','Content'=>'Treść','To translate the Method Title, go to the %1$sTranslation Dashboard%2$s.'=>'Aby przetłumaczyć tytuł metody, przejdź do %1$skokpitu tłumaczeń%2$s.','To translate Labels, go to the %1$sTranslation Dashboard%2$s.'=>'Aby przetłumaczyć etykiety, przejdź do %1$skokpitu tłumaczeń%2$s.','To translate custom product fields, save your changes here first, then go to the %1$sTranslation Dashboard%2$s.'=>'Aby przetłumaczyć pola własne produktu, najpierw zapisz tutaj zmiany, a następnie przejdź do %1$skokpitu tłumaczeń%2$s.','Calculate costs in other currencies automatically'=>'Obliczaj koszty w innych walutach automatycznie','Set costs in other currencies manually'=>'Ustawiaj koszty w innych walutach ręcznie','Bookings'=>'Rezerwacje','Resources Label'=>'Etykieta zasobów','Resources'=>'Zasoby','Person Types'=>'Typy osób','Person Type Name'=>'Nazwa typu osoby','Description'=>'Opis','Resources label'=>'Etykieta zasobów','To translate Resources, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'Aby przetłumaczyć zasoby, przejdź do %1$skokpitu tłumaczeń%2$s i wyślij powiązany produkt do tłumaczenia.','To translate Person Types, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'Aby przetłumaczyć typy osób, przejdź do %1$skokpitu tłumaczeń%2$s i wyślij powiązany produkt do tłumaczenia.','Booking currency'=>'Waluta rezerwacji','Composite Products ( Components )'=>'Produkty złożone ( komponenty )','Name'=>'Nazwa','Composite Products ( Scenarios )'=>'Produkty złożone ( scenariusze )','To translate global add-ons, go to the %1$sTranslation Dashboard%2$s.'=>'Aby przetłumaczyć dodatki globalne, przejdź do %1$skokpitu tłumaczeń%2$s.','Product Add-ons Group "%s"'=>'Grupa dodatków do produktu „%s”','Placeholder'=>'Tekst zastępczy','Options'=>'Opcje','Label'=>'Etykieta','To translate per-product add-ons, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'Aby przetłumaczyć dodatki dla poszczególnych produktów, przejdź do %1$skokpitu tłumaczeń%2$s i wyślij powiązany produkt do tłumaczenia.','Multi-currency settings'=>'Ustawienia wielowalutowości','Calculate prices in other currencies automatically'=>'Obliczaj ceny w innych walutach automatycznie','Set prices in other currencies manually'=>'Ustawiaj ceny w innych walutach ręcznie','Here you can set different prices for the %s in multiple currencies:'=>'Tutaj możesz ustawić różne ceny dla %s w wielu walutach:','Product Bundles'=>'Pakiety produktów','You can translate text for subscription products from the %1$sTranslation Dashboard%2$s.'=>'Tekst dla produktów subskrypcyjnych możesz przetłumaczyć w %1$skokpicie tłumaczeń%2$s.','Subscription Price'=>'Cena subskrypcji','Sign-up Fee'=>'Opłata wpisowa','Product tabs'=>'Zakładki produktu','Heading'=>'Nagłówek','To translate custom per-product tabs, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'Aby przetłumaczyć własne zakładki dla poszczególnych produktów, przejdź do %1$skokpitu tłumaczeń%2$s i wyślij powiązany produkt do tłumaczenia.','Custom Tabs'=>'Własne zakładki','Tab Title'=>'Tytuł zakładki','Quick Edit isn\'t available for product translations:'=>'Szybka edycja nie jest dostępna dla tłumaczeń produktów:','- To edit this product\'s translation, use the %1$sTranslation Dashboard%2$s.'=>'- Aby edytować tłumaczenie tego produktu, użyj %1$skokpitu tłumaczeń%2$s.','- To edit the original product, switch back to the default language.'=>'- Aby edytować oryginalny produkt, przełącz się z powrotem na język domyślny.','Multilingual Settings'=>'Ustawienia wielojęzyczności','Multicurrency Settings'=>'Ustawienia wielowalutowości','It’s recommended that you translate products from the %1$sTranslation Dashboard%2$s.'=>'Zaleca się tłumaczenie produktów z poziomu %1$skokpitu tłumaczeń%2$s.','WCML'=>'WCML','Shows a list of the products that existed in the cart before the cart is reset on the front end after switching the language or the currency. It will be hidden when there are no products to show.'=>'Wyświetla listę produktów, które znajdowały się w koszyku przed jego zresetowaniem na froncie po zmianie języka lub waluty. Widget zostanie ukryty, gdy nie będzie produktów do wyświetlenia.','Products before cart reset'=>'Produkty przed resetem koszyka','Switching language?'=>'Zmienić język?','You\'ve switched the language and there are items in the cart. If you keep the %s language, the cart will be emptied and you will have to add the items again to the cart.'=>'Zmieniono język, a w koszyku znajdują się produkty. Jeśli zachowasz język %s, koszyk zostanie opróżniony i trzeba będzie ponownie dodać do niego produkty.','Keep %s'=>'Zachowaj %s','Switch back to %s'=>'Przełącz z powrotem na %s','Reset cart option warning 1Because of some elements in your site configuration, when the users switch the currency or the language on the front end, the cart content might not be synchronized correctly.'=>'Ze względu na niektóre elementy konfiguracji witryny, gdy użytkownicy zmieniają walutę lub język na froncie, zawartość koszyka może nie być poprawnie synchronizowana.','Reset cart option warning 2It is recommended that you %s with the option to reset the cart in a situation like this.'=>'Zaleca się, aby %s z opcją resetowania koszyka w takiej sytuacji.','configure WPML Multilingual & Multicurrency for WooCommerce'=>'skonfigurować WPML Multilingual & Multicurrency for WooCommerce','More details'=>'Więcej szczegółów','Switching currency?'=>'Zmienić walutę?','Your cart is not empty! After you switched the currency, all items from the cart will be removed and you have to add them again.'=>'Twój koszyk nie jest pusty! Po zmianie waluty wszystkie produkty z koszyka zostaną usunięte i trzeba będzie dodać je ponownie.','Keep using %s'=>'Nadal używaj %s','Proceed'=>'Kontynuuj','Show reviews in all languages  (%s)'=>'Pokaż opinie we wszystkich językach (%s)','Show only reviews in %1$s (%2$s)'=>'Pokaż tylko opinie w języku %1$s (%2$s)','translated'=>'przetłumaczono','Show original'=>'Pokaż oryginał','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It is not compatible with  <a href="%1$s">WPML</a> versions prior %2$s.'=>'Wtyczka WPML Multilingual & Multicurrency for WooCommerce jest włączona, ale nie działa. Nie jest kompatybilna z wersjami <a href="%1$s">WPML</a> starszymi niż %2$s.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. Please finish the installation of WPML first.'=>'Wtyczka WPML Multilingual & Multicurrency for WooCommerce jest włączona, ale nie działa. Proszę najpierw dokończyć instalację WPML.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It is not compatible with  <a href="%1$s">Woocommerce</a> versions prior %2$s.'=>'Wtyczka WPML Multilingual & Multicurrency for WooCommerce jest włączona, ale nie działa. Nie jest kompatybilna z wersjami <a href="%1$s">Woocommerce</a> starszymi niż %2$s.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It is not compatible with  <a href="%1$s">WPML String Translation</a> versions prior %2$s.'=>'Wtyczka WPML Multilingual & Multicurrency for WooCommerce jest włączona, ale nie działa. Nie jest kompatybilna z wersjami <a href="%1$s">WPML String Translation</a> starszymi niż %2$s.','WPML support'=>'Wsparcie WPML','Default taxonomies must be translatable: 1/6Some taxonomies in your site are forced to be untranslatable. This is causing a problem when you\'re trying to run a multilingual WooCommerce site.'=>'Niektóre taksonomie w Twojej witrynie są wymuszone jako nieprzetłumaczalne. Powoduje to problem podczas próby prowadzenia wielojęzycznego sklepu WooCommerce.','Default taxonomies must be translatable: 2/6A plugin or the theme are probably doing this.'=>'Prawdopodobnie odpowiada za to wtyczka lub motyw.','Default taxonomies must be translatable: 3/6What you can do:'=>'Co możesz zrobić:','Default taxonomies must be translatable: 4/61. Temporarily disable plugins and see if this message disappears.'=>'1. Tymczasowo wyłącz wtyczki i sprawdź, czy ten komunikat zniknie.','Default taxonomies must be translatable: 5/62. Temporarily switch the theme and see if this message disappears.'=>'2. Tymczasowo zmień motyw i sprawdź, czy ten komunikat zniknie.','Default taxonomies must be translatable: 6/6It\'s best to contact %s, tell that you\'re getting this message and offer to send a Duplicator copy of the site. We will work with the theme/plugin author and fix the problem for good. In the meanwhile, we\'ll give you a temporary solution, so you\'re not stuck.'=>'Najlepiej skontaktować się z %s, poinformować o otrzymaniu tego komunikatu i zaoferować przesłanie kopii witryny z wtyczki Duplicator. Skontaktujemy się z autorem motywu/wtyczki i naprawimy problem na stałe. W międzyczasie podamy Ci rozwiązanie tymczasowe, aby nie blokować Twojej pracy.','and'=>'i','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective. It requires %s in order to work.'=>'Wtyczka WPML Multilingual & Multicurrency for WooCommerce jest włączona, ale nie działa. Do poprawnego działania wymaga %s.','Please %1$sactivate %2$s%3$s.'=>'Proszę %1$saktywować %2$s%3$s.','WPML Multilingual & Multicurrency for WooCommerce is enabled but not effective.'=>'Wtyczka WPML Multilingual & Multicurrency for WooCommerce jest włączona, ale nie działa.','Because this site uses the default permalink structure, you cannot use slug translation for product permalinks.'=>'Ponieważ ta witryna używa domyślnej struktury bezpośrednich odnośników, nie można używać tłumaczenia uproszczonych nazw dla odnośników produktów.','Please choose a different permalink structure or disable slug translation.'=>'Proszę wybrać inną strukturę bezpośrednich odnośników lub wyłączyć tłumaczenie uproszczonych nazw.','Permalink settings'=>'Ustawienia bezpośrednich odnośników','Configure products slug translation'=>'Skonfiguruj tłumaczenie uproszczonych nazw produktów','wpml-config.xml file missing from WPML Multilingual & Multicurrency for WooCommerce folder.'=>'Brak pliku wpml-config.xml w folderze WPML Multilingual & Multicurrency for WooCommerce.','Custom field %s configuration from wpml-config.xml file was altered!'=>'Konfiguracja pola własnego %s z pliku wpml-config.xml została zmieniona!','Custom type %s configuration from wpml-config.xml file was altered!'=>'Konfiguracja własnego typu wpisu %s z pliku wpml-config.xml została zmieniona!','Custom taxonomy %s configuration from wpml-config.xml file was altered!'=>'Konfiguracja własnej taksonomii %s z pliku wpml-config.xml została zmieniona!','We detected a problem in your WPML configuration: the %1$sproduct_type%2$s taxonomy is set as translatable and this would cause problems with translated products. You can fix this in the %3$sMultilingual Content Setup page%4$s.'=>'Wykryliśmy problem w konfiguracji WPML: taksonomia %1$sproduct_type%2$s jest ustawiona jako przetłumaczalna, co powodowałoby problemy z przetłumaczonymi produktami. Możesz to naprawić na %3$sstronie konfiguracji treści wielojęzycznych%4$s.','We detected that the %1$sproduct_type%2$s field was set incorrectly for some product translations. This happened because the product_type taxonomy was translated. You can fix this in the WPML Multilingual & Multicurrency for WooCommerce %3$stroubleshooting page%4$s.'=>'Wykryliśmy, że pole %1$sproduct_type%2$s zostało ustawione nieprawidłowo dla niektórych tłumaczeń produktów. Stało się tak, ponieważ taksonomia product_type została przetłumaczona. Możesz to naprawić na %3$sstronie rozwiązywania problemów%4$s WPML Multilingual & Multicurrency for WooCommerce.','Downloading translations... Please don\'t close this page.'=>'Pobieranie tłumaczeń... Proszę nie zamykać tej strony.','Order language:'=>'Język zamówienia:','All the products will be removed from the current order in order to change the language'=>'Wszystkie produkty zostaną usunięte z bieżącego zamówienia w celu zmiany języka','Quick edit "%s" inline'=>'Szybka edycja „%s” wiersza','Quick Edit'=>'Szybka edycja','Your settings have been saved.'=>'Twoje ustawienia zostały zapisane.','You do not have permission to perform this action.'=>'Nie masz uprawnień do wykonania tej czynności.','Choose a file'=>'Wybierz plik','At least one of these fields is required: title, content or excerpt'=>'Wymagane jest co najmniej jedno z tych pól: tytuł, treść lub krótki opis','This translation job will no longer be assigned to you. Other translators will be able take it and continue the translation.'=>'To zadanie tłumaczenia nie będzie już przypisane do Ciebie. Inni tłumacze będą mogli je przejąć i kontynuować tłumaczenie.','This field is locked for editing because WPML will copy its value from the original language.'=>'To pole jest zablokowane do edycji, ponieważ WPML skopiuje jego wartość z języka oryginalnego.','This is a translation of %1$s. Some of the fields are not editable. It\'s recommended that you translate products from the %2$sTranslation Dashboard%3$s.'=>'To jest tłumaczenie %1$s. Niektóre pola nie podlegają edycji. Zaleca się tłumaczenie produktów z poziomu %2$skokpitu tłumaczeń%3$s.','Cart'=>'Koszyk','Checkout'=>'Zamówienie','Checkout &rarr; Pay'=>'Zamówienie &rarr; zapłać','Order Received'=>'Otrzymano zamówienie','My Account'=>'Moje konto','Change Password'=>'Zmień hasło','Edit My Address'=>'Edytuj mój adres','Logout'=>'Wyloguj się','Lost Password'=>'Nie pamiętam hasła','View Order'=>'Zobacz zamówienie','Shop'=>'Sklep','To quickly translate this and other WooCommerce store pages, please run the %1$ssetup wizard%2$s.'=>'Aby szybko przetłumaczyć tę i inne strony sklepu WooCommerce, uruchom %1$skreatora konfiguracji%2$s.','To translate %1$s please use the %2$s translation%3$s page, inside the %4$sWPML Multilingual & Multicurrency for WooCommerce admin%5$s.'=>'Aby przetłumaczyć %1$s, użyj strony %2$s tłumaczenie%3$s wewnątrz %4$spanelu administracyjnego WPML Multilingual & Multicurrency for WooCommerce%5$s.','%d products left'=>'Pozostało produktów: %d','Synchronization complete!'=>'Synchronizacja zakończona!','Invalid taxonomy %s'=>'Nieprawidłowa taksonomia %s','Some translated %1$s have different %2$s assignments.'=>'Niektóre przetłumaczone %1$s mają różne przypisania %2$s.','Update %1$s for all translated %2$s'=>'Zaktualizuj %1$s dla wszystkich przetłumaczonych %2$s','All %1$s have the same %2$s assignments.'=>'Wszystkie %1$s mają te same przypisania %2$s.','Successfully updated %1$s for all translated %2$s.'=>'Pomyślnie zaktualizowano %1$s dla wszystkich przetłumaczonych %2$s.','Product Base'=>'Baza produktów','Product Tag Base'=>'Baza tagów produktów','Product Category Base'=>'Baza kategorii produktów','Product Attribute Base'=>'Baza atrybutów produktów','Attribute Slug'=>'Uproszczona nazwa atrybutu','Endpoint: %s'=>'Punkt końcowy: %s','You are using the same value as for the regular category base. This is known to create conflicts resulting in urls not working properly.'=>'Używasz tej samej wartości, co dla zwykłej bazy kategorii. Wiadomo, że tworzy to konflikty skutkujące nieprawidłowym działaniem adresów URL.','To translate attributes, go to the %1$sTranslation Dashboard%2$s and send the associated product for translation.'=>'Aby przetłumaczyć atrybuty, przejdź do %1$skokpitu tłumaczeń%2$s i wyślij powiązany produkt do tłumaczenia.','The default currency was changed. In order to show accurate prices in all currencies, you need to update the exchange rates under the %1$sMulti-currency%2$s configuration.'=>'Waluta domyślna została zmieniona. Aby wyświetlać dokładne ceny we wszystkich walutach, należy zaktualizować kursy wymiany w konfiguracji %1$sWielowalutowość%2$s.','Show all currencies'=>'Pokaż wszystkie waluty','Order currency:'=>'Waluta zamówienia:','All the products will be removed from the current order in order to change the currency'=>'Wszystkie produkty zostaną usunięte z bieżącego zamówienia w celu zmiany waluty','Currencies order updated'=>'Kolejność walut została zaktualizowana','Uploads'=>'Przesłane pliki','Currency switcher'=>'Przełącznik walut','Customize the currency switcher'=>'Dostosuj przełącznik walut','You haven\'t added any secondary currencies.'=>'Nie dodano żadnych walut pomocniczych.','Use custom settings for translations download files'=>'Użyj własnych ustawień dla plików pobierania tłumaczeń','Use the same files for translations'=>'Użyj tych samych plików dla tłumaczeń','Add separate download files for translations when you translate this product'=>'Dodaj oddzielne pliki pobierania dla tłumaczeń podczas tłumaczenia tego produktu','You have untranslated terms!'=>'Masz nieprzetłumaczone terminy!','Store URLs'=>'Adresy URL sklepu','Status'=>'Status','Troubleshooting'=>'Rozwiązywanie problemów','Translate Products'=>'Przetłumacz produkty','Go to WPML &rarr; Translation Dashboard to translate Products'=>'Przejdź do WPML &rarr; Kokpit tłumaczeń, aby przetłumaczyć produkty','Translate Taxonomy'=>'Przetłumacz taksonomię','Go to WPML &rarr; Taxonomy Translation to translate Taxonomy terms manually'=>'Przejdź do WPML &rarr; Tłumaczenie taksonomii, aby ręcznie przetłumaczyć terminy taksonomii','Prefer to translate manually?'=>'Wolisz tłumaczyć ręcznie?','To manually translate products, go to %1$sProducts%2$s and click on the "plus" icon.'=>'Aby ręcznie przetłumaczyć produkty, przejdź do sekcji %1$sProdukty%2$s i kliknij ikonę „plus”.','To manually translate product categories, tags and attributes, go to %1$sWPML &rarr; Taxonomy Translation%2$s.'=>'Aby ręcznie przetłumaczyć kategorie produktów, tagi i atrybuty, przejdź do %1$sWPML &rarr; Tłumaczenie taksonomii%2$s.','Translation'=>'Tłumaczenie','Translate the WooCommerce slugs (Shop, Product base, etc.) at WPML → Translations → Store URLs.'=>'Przetłumacz uproszczone nazwy WooCommerce (Sklep, Baza produktów itp.) w WPML → Tłumaczenia → Adresy URL sklepu.','Open Store URLs ›'=>'Otwórz adresy URL sklepu ›','Go to WPML → Translations → Dashboard to translate Products.'=>'Przejdź do WPML → Tłumaczenia → Kokpit, aby przetłumaczyć produkty.','Translate Products ›'=>'Przetłumacz produkty ›','Translate product taxonomies'=>'Przetłumacz taksonomie produktów','Go to WPML → Translations → Taxonomy to translate product categories, tags and attributes.'=>'Przejdź do WPML → Tłumaczenia → Taksonomia, aby przetłumaczyć kategorie produktów, tagi i atrybuty.','Translate Taxonomies ›'=>'Przetłumacz taksonomie ›','Products, media, downloads, reviews, cart and the variation translation sync — all in WPML → Settings → WCML.'=>'Produkty, media, pliki do pobrania, opinie, koszyk i synchronizacja tłumaczeń wariantów — wszystko w WPML → Ustawienia → WCML.','Open WCML Settings ›'=>'Otwórz ustawienia WCML ›','Configure currencies, exchange rates and currency switchers at WPML → Settings → Multicurrency.'=>'Skonfiguruj waluty, kursy wymiany i przełączniki walut w WPML → Ustawienia → Wielowalutowość.','Open Multicurrency ›'=>'Otwórz Wielowalutowość ›','Support'=>'Wsparcie','WCML status'=>'Status WCML','Diagnostic checks for store pages, products, taxonomies, multicurrency and plugins.'=>'Kontrole diagnostyczne dla stron sklepu, produktów, taksonomii, wielowalutowości i wtyczek.','Open WCML status ›'=>'Otwórz status WCML ›','Fix WCML translations'=>'Napraw tłumaczenia WCML','Safe bulk tools to sync product variations, galleries and stock; register missing reviews; create missing attribute translations.'=>'Bezpieczne narzędzia masowe do synchronizacji wariantów produktów, galerii i stanów magazynowych; rejestrowania brakujących opinii; tworzenia brakujących tłumaczeń atrybutów.','Open Fix WCML translations ›'=>'Otwórz Napraw tłumaczenia WCML ›','WCML configuration log'=>'Dziennik konfiguracji WCML','Read-only snapshot of the WCML configuration. Copy when WPML Support asks.'=>'Migawka konfiguracji WCML tylko do odczytu. Skopiuj, gdy poprosi o to wsparcie WPML.','Open WCML configuration log ›'=>'Otwórz dziennik konfiguracji WCML ›','WCML translation maintenance'=>'Konserwacja tłumaczeń WCML','Advanced repair tools — only run when WPML Support asks you to.'=>'Zaawansowane narzędzia naprawcze — uruchamiaj tylko na prośbę wsparcia WPML.','Open WCML translation maintenance ›'=>'Otwórz konserwację tłumaczeń WCML ›','WPML is installed on this site, so WCML\'s controls have moved into WPML. Pick the area you need.'=>'WPML jest zainstalowany na tej stronie, więc elementy sterujące WCML zostały przeniesione do WPML. Wybierz obszar, którego potrzebujesz.','Translatable?'=>'Przetłumaczalne?','Enable this if you want to translate attribute values with WPML Multilingual & Multicurrency for WooCommerce'=>'Włącz to, jeśli chcesz tłumaczyć wartości atrybutów za pomocą WPML Multilingual & Multicurrency for WooCommerce','Existing translations and variations associated will be deleted.'=>'Istniejące tłumaczenia i powiązane warianty zostaną usunięte.','Products removed after switching to %s:'=>'Produkty usunięte po przełączeniu na %s:','Clear list'=>'Wyczyść listę','Products Synchronization'=>'Synchronizacja produktów','Configure specific product properties that should be synced to translations.'=>'Skonfiguruj określone właściwości produktów, które powinny być synchronizowane z tłumaczeniami.','Sync publishing date for translated products.'=>'Synchronizuj datę publikacji dla przetłumaczonych produktów.','Sync products and product taxonomies order.'=>'Synchronizuj kolejność produktów i taksonomii produktów.','Products Media Synchronization'=>'Synchronizacja mediów produktów','Configure thumbnail and gallery synchronization to translations.'=>'Skonfiguruj synchronizację miniatur i galerii z tłumaczeniami.','Display original images on the translated product front page if images not specified'=>'Wyświetlaj oryginalne obrazy na stronie przetłumaczonego produktu, jeśli nie określono obrazów','Products Download Files'=>'Pliki pobierania produktów','If you are using downloadable products, you can choose to have their paths
                                            synchronized, or seperate for each language.'=>'Jeśli korzystasz z produktów do pobrania, możesz wybrać, czy ich ścieżki
                                            mają być synchronizowane, czy oddzielne dla każdego języka.','Add separate download files for translations when translating products'=>'Dodaj oddzielne pliki pobierania dla tłumaczeń podczas tłumaczenia produktów','Product reviews'=>'Opinie o produktach','Define how to display product reviews on the product page by default. The customer will be still able to filter reviews by language.'=>'Zdefiniuj, jak domyślnie wyświetlać opinie o produktach na stronie produktu. Klient nadal będzie mógł filtrować opinie według języka.','By default, show reviews in all languages'=>'Domyślnie pokazuj opinie we wszystkich językach','You can choose to clear the cart contents when you change language or currency in case you have problems in cart or checkout page'=>'Możesz wyczyścić zawartość koszyka przy zmianie języka lub waluty, jeśli napotkasz problemy na stronie koszyka lub zamówienia','Switching languages when there are items in the cart'=>'Zmiana języka, gdy w koszyku znajdują się produkty','Synchronize cart content when switching languages'=>'Synchronizuj zawartość koszyka przy zmianie języka','Prompt for a confirmation and reset the cart'=>'Poproś o potwierdzenie i zresetuj koszyk','Switching currencies when there are items in the cart'=>'Zmiana waluty, gdy w koszyku znajdują się produkty','Synchronize cart content when switching currencies'=>'Synchronizuj zawartość koszyka przy zmianie waluty','This feature was disabled. Please enable %1$sWPML cookies%2$s to continue.'=>'Ta funkcja została wyłączona. Aby kontynuować, włącz %1$spliki cookie WPML%2$s.','Not sure which option to choose? Read about %1$spotential issues when switching languages and currencies while the cart has items%2$s.'=>'Nie wiesz, którą opcję wybrać? Przeczytaj o %1$spotencjalnych problemach przy zmianie języka i waluty, gdy w koszyku znajdują się produkty%2$s.','Product Translation Interface'=>'Interfejs tłumaczenia produktów','The recommended way is using the WPML Translation Editor. It is streamlined for making the translation process much easier while also providing a much better integration with various WooCommerce extensions.'=>'Zalecanym sposobem jest korzystanie z Edytora tłumaczeń WPML. Jest on zoptymalizowany pod kątem ułatwienia procesu tłumaczenia, zapewniając jednocześnie znacznie lepszą integrację z różnymi rozszerzeniami WooCommerce.','WPML Translation Editor'=>'Edytor tłumaczeń WPML','Native WooCommerce product editing screen'=>'Natywny ekran edycji produktu WooCommerce','If you are using a page builder to design WooCommerce products, you should only use WPML\'s Translation Editor.'=>'Jeśli używasz page buildera do projektowania produktów WooCommerce, powinieneś korzystać wyłącznie z Edytora tłumaczeń WPML.','OK (translate with the WordPress editor)'=>'OK (tłumacz w edytorze WordPress)','Cancel (stay with the Translation Editor)'=>'Anuluj (pozostań przy Edytorze tłumaczeń)','Set different slugs in different languages for %s on WPML Multilingual & Multicurrency for WooCommerce URLs translations page'=>'Ustaw różne uproszczone nazwy w różnych językach dla %s na stronie tłumaczeń adresów URL WPML Multilingual & Multicurrency for WooCommerce','To translate the attribute slug, please set the option "Enable archives?" for the attribute %s in WooCommerce'=>'Aby przetłumaczyć uproszczoną nazwę atrybutu, włącz opcję „Włączyć archiwa?” dla atrybutu %s w WooCommerce','Synchronize attributes and update product variations'=>'Zsynchronizuj atrybuty i zaktualizuj warianty produktów','This will automatically generate variations for translated products corresponding to recently translated attributes.'=>'To automatycznie wygeneruje warianty dla przetłumaczonych produktów odpowiadające niedawno przetłumaczonym atrybutom.','Currently, there are %s variations that need to be created.'=>'Obecnie istnieje %s wariantów, które muszą zostać utworzone.','Synchronize %s assignment in content'=>'Zsynchronizuj przypisanie %s w treści','This action lets you automatically apply the %s taxonomy to your content in different languages. It will scan the original content and apply the same taxonomy to translated content.'=>'Ta akcja pozwala automatycznie zastosować taksonomię %s do treści w różnych językach. Przeskanuje ona oryginalną treść i zastosuje tę samą taksonomię do przetłumaczonej treści.','Please make a backup of your database before using these tools'=>'Przed użyciem tych narzędzi wykonaj kopię zapasową bazy danych','There are <strong>%s product(s)</strong> in total.'=>'Łącznie istnieje <strong>%s produktów</strong>.','There are <strong>%s product(s)</strong> with variations.'=>'Istnieje <strong>%s produktów</strong> z wariantami.','There are <strong>%s variation(s)</strong> in total.'=>'Łącznie istnieje <strong>%s wariantów</strong>.','Synchronize data into translations'=>'Synchronizuj dane w tłumaczeniach','Synchronize product variations'=>'Zsynchronizuj warianty produktów','Synchronize products image galleries'=>'Zsynchronizuj galerie obrazów produktów','Synchronize metadata for product categories (display type, thumbnail)'=>'Zsynchronizuj metadane dla kategorii produktów (typ wyświetlania, miniatura)','Synchronize stock for products and product variations'=>'Zsynchronizuj stany magazynowe dla produktów i wariantów produktów','Fix multilingual information'=>'Napraw informacje wielojęzyczne','Fix incorrect or missing translation links for product variations'=>'Napraw nieprawidłowe lub brakujące powiązania tłumaczeń dla wariantów produktów','Fix product taxonomies'=>'Napraw taksonomie produktów','Set product types as not translatable and delete unwanted translations'=>'Ustaw typy produktów jako nieprzetłumaczalne i usuń niechciane tłumaczenia','Create missing translations for product attributes:'=>'Utwórz brakujące tłumaczenia dla atrybutów produktów:','To translate product taxonomies, go to the %1$sTaxonomy Translation%2$s page.'=>'Aby przetłumaczyć taksonomie produktów, przejdź do strony %1$sTłumaczenie taksonomii%2$s.','none'=>'brak','Fix missing product reviews'=>'Napraw brakujące opinie o produktach','Allow to translate missing product reviews'=>'Zezwól na tłumaczenie brakujących opinii o produktach','To translate product reviews, go to the %1$sTranslation Dashboard%2$s.'=>'Aby przetłumaczyć opinie o produktach, przejdź do %1$sKokpitu tłumaczeń%2$s.','Cleanup tools'=>'Narzędzia czyszczące','Remove unused custom fields from product and variation translations'=>'Usuń nieużywane pola własne z tłumaczeń produktów i wariantów','Run the selected tools'=>'Uruchom wybrane narzędzia','Processing'=>'Przetwarzanie','WPML Multilingual & Multicurrency for WooCommerce settings'=>'Ustawienia WPML Multilingual & Multicurrency for WooCommerce','%s items processed'=>'Przetworzono %s elementów','Processing...'=>'Przetwarzanie...','Completed'=>'Zakończono','Something went wrong, please reload the page and try again'=>'Coś poszło nie tak, odśwież stronę i spróbuj ponownie','Clear all colors'=>'Wyczyść wszystkie kolory','Gray'=>'Szary','White'=>'Biały','Blue'=>'Niebieski','Border'=>'Obramowanie','Current currency font color'=>'Kolor czcionki bieżącej waluty','Other currency font color'=>'Kolor czcionki innej waluty','Current currency background color'=>'Kolor tła bieżącej waluty','Other currency background color'=>'Kolor tła innej waluty','Currency switcher style'=>'Styl przełącznika walut','Core'=>'Podstawowy','Custom'=>'Własny','Allowed HTML tags: <img> <span> <u> <strong> <em>'=>'Dozwolone tagi HTML: <img> <span> <u> <strong> <em>','Template for currency switcher'=>'Szablon przełącznika walut','Available parameters'=>'Dostępne parametry','Default: %name% (%1$symbol%) - %2$code%'=>'Domyślnie: %name% (%1$symbol%) - %2$code%','Hide more'=>'Ukryj więcej','You can customize the currency switcher template using these parameters:'=>'Możesz dostosować szablon przełącznika walut, używając następujących parametrów:','%1$s: Full name of the currency (e.g., “Euro”).'=>'%1$s: Pełna nazwa waluty (np. „Euro”).','%1$s: Standard symbol representing the currency (e.g., “$” or “€”).'=>'%1$s: Standardowy symbol reprezentujący walutę (np. „$” lub „€”).','%1$s: Standard code representing the currency (e.g., USD for United States Dollar).'=>'%1$s: Standardowy kod reprezentujący walutę (np. USD dla dolara amerykańskiego).','Additionally, you can use HTML tags %1$s(img, span, em, strong, u)%2$s to customize the output when the switcher style is set to %1$sList of currencies%2$s, %3$sin line with official HTML standards for the select tag%4$s.'=>'Dodatkowo możesz użyć tagów HTML %1$s(img, span, em, strong, u)%2$s, aby dostosować wynik, gdy styl przełącznika jest ustawiony na %1$sLista walut%2$s, %3$szgodnie z oficjalnymi standardami HTML dla tagu select%4$s.','Currency switcher colors'=>'Kolory przełącznika walut','Color theme'=>'Motyw kolorystyczny','Normal'=>'Normalny','Hover'=>'Po najechaniu','Select a preset'=>'Wybierz gotowe ustawienie','Widget area'=>'Obszar widżetów','Widget title'=>'Tytuł widżetu','-- Choose a widget area --'=>'-- Wybierz obszar widżetów --','Preview'=>'Podgląd','Regular Price'=>'Cena podstawowa','Sale Price'=>'Cena promocyjna','Multi-currency is enabled, but no secondary currencies have been set. %1$sAdd secondary currency%2$s.'=>'Obsługa wielu walut jest włączona, ale nie ustawiono żadnych walut pomocniczych. %1$sDodaj walutę pomocniczą%2$s.','Click to see the prices in the other currencies as they are currently shown on the front end.'=>'Kliknij, aby zobaczyć ceny w innych walutach, tak jak są one obecnie wyświetlane na stronie.','Show'=>'Pokaż','Hide'=>'Ukryj','Enter prices in other currencies'=>'Wprowadź ceny w innych walutach','Hide prices in other currencies'=>'Ukryj ceny w innych walutach','Determined automatically based on exchange rate'=>'Określana automatycznie na podstawie kursu wymiany','Schedule'=>'Harmonogram','Same as default currency'=>'Taki sam jak w walucie bazowej','Set dates'=>'Ustaw daty','Collapse'=>'Zwiń','From&hellip;'=>'Od&hellip;','To&hellip;'=>'Do&hellip;','Please enter in a value less than the regular price'=>'Wprowadź wartość mniejszą niż cena podstawowa','never'=>'nigdy','Automatic Exchange Rates'=>'Automatyczne kursy wymiany','Enable automatic exchange rates'=>'Włącz automatyczne kursy wymiany','Exchange rates source'=>'Źródło kursów wymiany','Lifting charge'=>'Narzut na kurs','The lifting charge adjusts the exchange rate provided by the selected service before it is saved. The exchange rates displayed in the table above include the lifting charge.'=>'Narzut na kurs dostosowuje kurs wymiany dostarczony przez wybraną usługę przed jego zapisaniem. Kursy wymiany wyświetlane w powyższej tabeli zawierają narzut.','Exchange rate = %s exchange rate x (1 + lifting charge / 100)'=>'Kurs wymiany = %s kurs wymiany x (1 + narzut na kurs / 100)','API key (required)'=>'Klucz API (wymagany)','Update frequency'=>'Częstotliwość aktualizacji','Update manually now'=>'Aktualizuj ręcznie teraz','You have to save all settings before updating exchange rates'=>'Musisz zapisać wszystkie ustawienia przed aktualizacją kursów wymiany','Manually'=>'Ręcznie','Hourly'=>'Co godzinę','Daily'=>'Codziennie','Weekly on'=>'Co tydzień w','Monthly on the'=>'Co miesiąc dnia','Enter API key'=>'Wprowadź klucz API','WARNING! Minor limitations include 1000 requests/month limit and EUR being the only available base currency for customers using a free account. If you need more than 1000 requests per month or want to use all 170 available base currencies, you’ll need to choose one of the paid plans starting at only $10 per month.'=>'OSTRZEŻENIE! Niewielkie ograniczenia obejmują limit 1000 żądań miesięcznie, a EUR jest jedyną dostępną walutą bazową dla klientów korzystających z darmowego konta. Jeśli potrzebujesz więcej niż 1000 żądań miesięcznie lub chcesz korzystać ze wszystkich 170 dostępnych walut bazowych, musisz wybrać jeden z płatnych planów zaczynających się od zaledwie $10 miesięcznie.','Updating the exchange rates on an hourly basis generates around 744 API calls a month. Please check that your exchange rates source can accommodate this higher usage.'=>'Aktualizowanie kursów wymiany co godzinę generuje około 744 wywołań API miesięcznie. Sprawdź, czy Twoje źródło kursów wymiany może obsłużyć takie zużycie.','Last updated: %s'=>'Ostatnia aktualizacja: %s','Exchange rates updated successfully'=>'Kursy wymiany zostały pomyślnie zaktualizowane','Visit website'=>'Odwiedź stronę','Enable/disable'=>'Włącz/wyłącz','The multi-currency mode cannot be enabled as a specific currency was not set. Go to the %1$sWooCommerce settings%2$s page and select the default currency for your store.'=>'Tryb wielowalutowy nie może zostać włączony, ponieważ nie ustawiono konkretnej waluty. Przejdź do strony %1$sustawień WooCommerce%2$s i wybierz domyślną walutę dla swojego sklepu.','Enable the multicurrency mode'=>'Włącz tryb wielowalutowy','Multicurrency documentation'=>'Dokumentacja wielowalutowości','Custom prices'=>'Ceny własne','Show only products with %1$scustom prices%2$s in secondary currencies'=>'Pokaż tylko produkty z %1$scenami własnymi%2$s w walutach pomocniczych','When enabled, products with prices based on the exchange rate are hidden'=>'Po włączeniu produkty z cenami opartymi na kursie wymiany zostaną ukryte','The changes you made will be lost if you navigate away from this page.'=>'Wprowadzone zmiany zostaną utracone, jeśli opuścisz tę stronę.','At least one currency must be enabled for this language!'=>'Dla tego języka musi być włączona co najmniej jedna waluta!','Currency switcher options'=>'Opcje przełącznika walut','All currency switchers in your site are affected by the settings in this section.'=>'Ustawienia w tej sekcji dotyczą wszystkich przełączników walut w Twojej witrynie.','Order of currencies'=>'Kolejność walut','Additional CSS'=>'Dodatkowy CSS','Widget Currency Switcher'=>'Widżet przełącznika walut','Product page Currency Switcher'=>'Przełącznik walut na stronie produktu','Position'=>'Pozycja','Actions'=>'Działania','Action'=>'Działanie','Edit currency switcher'=>'Edytuj przełącznik walut','Add a new currency switcher to a widget area'=>'Dodaj nowy przełącznik walut do obszaru widżetów','Your theme does not support a currency switcher widget. Please %1$sadd your currency switcher%2$s using a shortcode or PHP.'=>'Twój motyw nie obsługuje widżetu przełącznika walut. %1$sDodaj przełącznik walut%2$s, używając shortcode lub PHP.','Currency switcher preview'=>'Podgląd przełącznika walut','Drag and drop the currencies to change their order'=>'Przeciągnij i upuść waluty, aby zmienić ich kolejność','Show a currency switcher on the product page template'=>'Pokaż przełącznik walut w szablonie strony produktu','Edit Product Currency Switcher'=>'Edytuj przełącznik walut produktu','New Widget Area Currency Switcher'=>'Nowy przełącznik walut w obszarze widżetów','Edit %s Currency Switcher'=>'Edytuj przełącznik walut %s','Which product attributes should be translatable?'=>'Które atrybuty produktów powinny być przetłumaczalne?','WPML allows you to %1$stranslate your product attributes%2$s. Some attributes, like the ones based on numbers and codes, can be universal and might not need to be translated.'=>'WPML pozwala %1$sprzetłumaczyć atrybuty produktów%2$s. Niektóre atrybuty, np. te oparte na liczbach i kodach, mogą być uniwersalne i nie wymagać tłumaczenia.','Select which attributes in your store should be translatable:'=>'Wybierz, które atrybuty w Twoim sklepie powinny być przetłumaczalne:','There are no attributes defined'=>'Nie zdefiniowano żadnych atrybutów','Continue'=>'Kontynuuj','Go back'=>'Wstecz','WPML Multilingual & Multicurrency for WooCommerce › Setup Wizard'=>'WPML Multilingual & Multicurrency for WooCommerce › Setup Wizard','Let\'s make your WooCommerce store multilingual'=>'Uczyńmy Twój sklep WooCommerce wielojęzycznym','To get started, we need to set up the following:'=>'Aby rozpocząć, musimy skonfigurować następujące elementy:','Create store pages in all your site\'s languages'=>'Utwórz strony sklepu we wszystkich językach witryny','Choose which product attributes you want to translate'=>'Wybierz, które atrybuty produktów chcesz przetłumaczyć','Set your translation options'=>'Ustaw opcje tłumaczenia','Decide if you want to add multiple currencies to your store'=>'Zdecyduj, czy chcesz dodać wiele walut do swojego sklepu','Let\'s continue'=>'Kontynuujmy','I\'ll do the setup later'=>'Skonfiguruję to później','Do you want to add more currencies to your store?'=>'Czy chcesz dodać więcej walut do swojego sklepu?','You will be able to:'=>'Będziesz mieć możliwość:','Add a currency switcher to your store'=>'Dodania przełącznika walut do swojego sklepu','Set exchange rates'=>'Ustawienia kursów wymiany','Create custom pricing in each currency'=>'Utworzenia własnych cen w każdej walucie','And more!'=>'I wiele więcej!','Yes, enable multicurrency mode'=>'Tak, włącz tryb wielowalutowy','No, use only one currency'=>'Nie, używaj tylko jednej waluty','Make your store multilingual'=>'Uczyń swój sklep wielojęzycznym','Set up %1$sWPML Multilingual & Multicurrency for WooCommerce%2$s to translate your store and add more currencies.'=>'Skonfiguruj %1$sWPML Multilingual & Multicurrency for WooCommerce%2$s, aby przetłumaczyć swój sklep i dodać więcej walut.','Start the Setup Wizard'=>'Uruchom Setup Wizard','Click continue to create missing WooCommerce pages translate your store pages into the following languages:'=>'Kliknij kontynuuj, aby utworzyć brakujące strony WooCommerce i przetłumaczyć strony sklepu na następujące języki:','Click continue to translate your store pages into the following languages:'=>'Kliknij kontynuuj, aby przetłumaczyć strony sklepu na następujące języki:','WPML automatically generates translated versions of default WooCommerce pages, such as Shop, Account, Checkout, and Cart.'=>'WPML automatycznie generuje przetłumaczone wersje domyślnych stron WooCommerce, takich jak Sklep, Moje konto, Zamówienie i Koszyk.','Configuration Warnings'=>'Ostrzeżenia konfiguracyjne','Your product permalink base is not translated to:'=>'Baza bezpośrednich odnośników produktów nie jest przetłumaczona na:','Translate URLs'=>'Tłumacz adresy URL','Running WPML Multilingual & Multicurrency for WooCommerce with default language other than English.'=>'Uruchamianie WPML Multilingual & Multicurrency for WooCommerce z językiem domyślnym innym niż angielski.','This may cause problems with URLs in different languages.'=>'Może to powodować problemy z adresami URL w różnych językach.','Change default language'=>'Zmień język domyślny','There are some settings that require careful attention.'=>'Niektóre ustawienia wymagają szczególnej uwagi.','Some settings from the WPML Multilingual & Multicurrency for WooCommerce wpml-config.xml file have been overwritten.'=>'Niektóre ustawienia z pliku wpml-config.xml wtyczki WPML Multilingual & Multicurrency for WooCommerce zostały nadpisane.','You should check WPML configuration files added by other plugins or manual settings on the %s section.'=>'Powinieneś sprawdzić pliki konfiguracyjne WPML dodane przez inne wtyczki lub ustawienia ręczne w sekcji %s.','Multilingual Content Setup'=>'Ustawienia treści wielojęzycznych','Media'=>'Media','%s is not active.'=>'%s nie jest aktywny.','%s is not required in order to run WPML Multilingual & Multicurrency for WooCommerce but it’s recommended if you want to use separate product images and galleries for different languages.'=>'%s nie jest wymagany do działania WPML Multilingual & Multicurrency for WooCommerce, ale jest zalecany, jeśli chcesz używać oddzielnych obrazów produktów i galerii dla różnych języków.','%s is installed and active.'=>'%s jest zainstalowany i aktywny.','Secondary currencies: %s'=>'Waluty pomocnicze: %s','Multi-currency is not enabled.'=>'Tryb wielowalutowy nie jest włączony.','Add Currencies'=>'Dodaj waluty','Products Missing Translations'=>'Produkty bez tłumaczeń','%1$d %2$s translation missing.'=>'Brak tłumaczenia dla %1$d produktu w języku %2$s.','%1$d %2$s translations missing.'=>'Brak tłumaczeń dla %1$d produktów w języku %2$s.','Right now, there are no products needing translation.'=>'Obecnie nie ma produktów wymagających tłumaczenia.','Plugins Status'=>'Status wtyczek','%s is set up.'=>'%s jest skonfigurowany.','%s is not set up.'=>'%s nie jest skonfigurowany.','WPML Multilingual & Multicurrency for WooCommerce depends on several plugins to work. If any required plugin is missing, you should install and activate it.'=>'WPML Multilingual & Multicurrency for WooCommerce wymaga do działania kilku wtyczek. Jeśli brakuje jakiejkolwiek wymaganej wtyczki, należy ją zainstalować i aktywować.','WooCommerce Store Pages'=>'Strony sklepu WooCommerce','To run a multilingual e-commerce site, you need to have the WooCommerce shop pages translated to all the site\'s languages. Once all the pages are installed you can add the translations for them from this menu.'=>'Aby prowadzić wielojęzyczną witrynę e-commerce, strony sklepu WooCommerce muszą zostać przetłumaczone na wszystkie języki witryny. Po zainstalowaniu wszystkich stron można dodać ich tłumaczenia z poziomu tego menu.','One or more WooCommerce pages have not been created.'=>'Jedna lub więcej stron WooCommerce nie zostało utworzonych.','Install WooCommerce Pages'=>'Zainstaluj strony WooCommerce','WooCommerce store pages do not exist for these languages:'=>'Strony sklepu WooCommerce nie istnieją dla następujących języków:','Create missing translations'=>'Utwórz brakujące tłumaczenia','These pages are currently being translated by translators via WPML: '=>'Te strony są obecnie tłumaczone przez tłumaczy za pośrednictwem WPML: ','WooCommerce store pages are translated to all the site\'s languages.'=>'Strony sklepu WooCommerce są przetłumaczone na wszystkie języki witryny.','Taxonomies Missing Translations'=>'Taksonomie z brakującymi tłumaczeniami','To run a fully translated site, you should translate all taxonomy terms. Some store elements, such as variations, depend on taxonomy translation.'=>'Aby prowadzić w pełni przetłumaczoną witrynę, należy przetłumaczyć wszystkie terminy taksonomii. Niektóre elementy sklepu, takie jak warianty, zależą od tłumaczenia taksonomii.','%s do not require translation.'=>'%s nie wymagają tłumaczenia.','This taxonomy requires translation.'=>'Ta taksonomia wymaga tłumaczenia.','%1$d %2$s is missing translations.'=>'%1$d %2$s nie ma tłumaczeń.','%1$d %2$s are missing translations.'=>'%1$d %2$s nie mają tłumaczeń.','Translate %s'=>'Przetłumacz %s','This taxonomy does not require translation.'=>'Ta taksonomia nie wymaga tłumaczenia.','All %s are translated.'=>'Wszystkie %s są przetłumaczone.','Right now, there are no taxonomy terms needing translation.'=>'Obecnie nie ma żadnych terminów taksonomii wymagających tłumaczenia.','To configure product taxonomies or attributes as translatable or not translatable, go to the %1$sMultilingual Content Setup%2$s'=>'Aby skonfigurować taksonomie produktów lub atrybuty jako możliwe do tłumaczenia lub nie, przejdź do sekcji %1$sUstawienia treści wielojęzycznych%2$s','Original'=>'Oryginał','Translation to'=>'Tłumaczenie na','Product Shop Base'=>'Baza sklepu z produktami','Original language'=>'Język oryginalny','Update translation'=>'Aktualizuj tłumaczenie','Add translation'=>'Dodaj tłumaczenie','Edit translation'=>'Edytuj tłumaczenie','This page allows you to translate all strings that are being used by WooCommerce in building different type of urls. Translating them enables you to have fully localized urls that match the language of the pages.'=>'Ta strona umożliwia przetłumaczenie wszystkich ciągów znaków używanych przez WooCommerce do budowania różnych typów adresów URL. Ich przetłumaczenie pozwala na posiadanie w pełni zlokalizowanych adresów URL pasujących do języka stron.','You can enter or edit your default values on the %1$sPermalinks settings%2$s page or, for the endpoints, on the WooCommerce %3$sAdvanced settings%4$s page.'=>'Możesz wprowadzić lub edytować domyślne wartości na stronie %1$sustawienia bezpośrednich odnośników%2$s lub, w przypadku punktów końcowych, na stronie WooCommerce %3$sUstawienia zaawansowane%4$s.','permalinks settings'=>'ustawienia bezpośrednich odnośników','Account settings'=>'Ustawienia konta','Slug type'=>'Typ uproszczonej nazwy','Original Slug'=>'Oryginalna uproszczona nazwa','Shop page'=>'Strona sklepu','Product base'=>'Baza produktów','Product category base'=>'Baza kategorii produktów','Product tag base'=>'Baza tagów produktów','Product attribute base'=>'Baza atrybutów produktów','Attribute slug: %s'=>'Uproszczona nazwa atrybutu: %s','Product'=>'Produkt','Slug'=>'Uproszczona nazwa','Content / Description'=>'Treść / Opis','Excerpt'=>'Zajawka','Purchase note'=>'Uwaga do zakupu','Images'=>'Obrazki','Custom Product attributes'=>'Własne atrybuty produktu','Value(s)'=>'Wartość(ci)','Custom Fields'=>'Pola własne','Variations data'=>'Dane wariantów','Download Files for Variation #%s'=>'Pliki do pobrania dla wariantu #%s','Download Files'=>'Pliki do pobrania','File URL'=>'Adres URL pliku','External Product'=>'Produkt zewnętrzny','Product url'=>'Adres URL produktu','Button text'=>'Tekst przycisku','Changes in these translations will affect terms in general! ( Not only for this product )'=>'Zmiany w tych tłumaczeniach wpłyną na ogólne terminy! ( Nie tylko dla tego produktu )','Content, title, and excerpt are empty.'=>'Treść, tytuł i zajawka są puste.']];